		const ns = Object.assign({}, state);
		let o = ns;
		let part;
		for (let i = 0; i < this.parts.length - 1; i++) {
			part = this.parts[i];
			const no = Object.assign({}, o[part]);
			o[part] = no;
			o = no;
		}
